const txt = v => String(v ?? '').trim().replace(/^'/, '');
const so = v => String(v ?? '').replace(/\D/g, '');
// Prefixo ' faz o Google Sheets gravar como texto
// (preserva zeros a esquerda, 44 digitos da chave e referencias como 27.00020)
const T = v => "'" + txt(v);
const agoraISO = () => $now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd HH:mm:ss');
const isoParaBR = iso => {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(txt(iso));
  return m ? `${m[3]}/${m[2]}/${m[1]}` : '';
};
const normSerie = s => (so(s) ? String(Number(so(s))) : '');
const identificacao = (nf, serie) => `${so(nf).padStart(9, '0')}-${normSerie(serie)}`;

function dvChave(c43) {
  let peso = 2, soma = 0;
  for (let i = c43.length - 1; i >= 0; i--) {
    soma += Number(c43[i]) * peso;
    peso = peso === 9 ? 2 : peso + 1;
  }
  const r = soma % 11;
  return r < 2 ? 0 : 11 - r;
}

// Valida a entrada do formulario. Retorna {nf, serie, chave} ou {erro}.
// Apenas digitos seguem para o SQL (protecao contra SQL injection).
function validarEntrada(nfIn, serieIn, chaveIn) {
  const chaveTxt = String(chaveIn ?? '').trim();
  if (chaveTxt) {
    const chave = so(chaveTxt);
    if (chave.length !== 44) return { erro: 'A chave de acesso deve ter 44 dígitos.' };
    if (dvChave(chave.slice(0, 43)) !== Number(chave[43])) {
      return { erro: 'Chave de acesso inválida: o dígito verificador não confere.' };
    }
    // Layout da chave: serie nas posicoes 23-25, numero da NF nas 26-34
    return { nf: chave.slice(25, 34), serie: normSerie(chave.slice(22, 25)), chave };
  }
  const nfTxt = String(nfIn ?? '').trim();
  const serieTxt = String(serieIn ?? '').trim();
  if (!nfTxt || !serieTxt) return { erro: 'Informe a nota fiscal e a série, ou a chave de acesso.' };
  if (!/^\d{1,9}$/.test(nfTxt)) return { erro: 'A nota fiscal deve conter apenas números (até 9 dígitos).' };
  if (!/^\d{1,3}$/.test(serieTxt)) return { erro: 'A série deve conter apenas números (até 3 dígitos).' };
  return { nf: nfTxt.padStart(9, '0'), serie: normSerie(serieTxt), chave: '' };
}

