  if (!/^\d{1,9}$/.test(nfTxt)) return { erro: 'A nota fiscal deve conter apenas números (até 9 dígitos).' };
  if (!/^\d{1,3}$/.test(serieTxt)) return { erro: 'A série deve conter apenas números (até 3 dígitos).' };
  return { nf: nfTxt.padStart(9, '0'), serie: normSerie(serieTxt), chave: '' };
}

// ============================================================
// COMPARAR SQL x PLANILHA E PREPARAR ATUALIZACOES
// Torre de Controle Importados - SUL x RIO
// ============================================================
// Regras:
// - Dados do faturamento: gravados apenas se a celula estiver vazia.
// - Dados operacionais: gravados quando mudam; nunca apaga com vazio.
// - RECEBIMENTO_RIO = Sim sem data: grava a data/hora atual (BRT).
// - Somente linhas com alteracao seguem para o Google Sheets.
const linhas = $('Ler planilha (horário)').all().map(i => i.json);
const consulta = $('Preparar consulta').first().json;
const sql = $input.all().map(i => i.json).filter(d => txt(d.CHAVE_NFE));

const porChave = new Map();
const porNf = new Map();
for (const d of sql) {
  porChave.set(txt(d.CHAVE_NFE), d);
  const k = identificacao(d.NF_SAIDA, d.SERIE_NF);
  if (!porNf.has(k)) porNf.set(k, []);
  porNf.get(k).push(d);
}

const consultadas = new Set(
  [...String(consulta.chaves || '').split(','), ...String(consulta.nfs || '').split(',')].filter(Boolean)
);

// IDENTIFICACAO duplicada: nao atualiza (chave de atualizacao ambigua)
const contagem = new Map();
for (const r of linhas) {
  const id = txt(r.IDENTIFICACAO);
  if (id) contagem.set(id, (contagem.get(id) || 0) + 1);
}

const DATAS = ['DATA_AGENDAMENTO', 'INICIO_CONFERENCIA_SUL', 'FIM_CONFERENCIA_SUL',
               'DATA_EMBARQUE', 'PREVISAO_CHEGADA', 'DATA_ENTRADA_FISCAL'];
const agora = agoraISO();
const out = [];

for (const r of linhas) {
  const id = txt(r.IDENTIFICACAO);
  if (!id || contagem.get(id) > 1) continue;

  const upd = {};
  const setTexto = (campo, valor, comoTexto = false, soSeVazio = false) => {
    const novo = txt(valor);
    if (!novo) return;
    const atual = txt(r[campo]);
    if (soSeVazio && atual) return;
    if (novo !== atual) upd[campo] = comoTexto ? T(novo) : novo;
  };
  const setNumero = (campo, valor) => {
    if (valor === null || valor === undefined || valor === '') return;
    if (txt(r[campo])) return;
    upd[campo] = Number(valor);
  };
  const setData = (campo, iso) => {
    const br = isoParaBR(iso);
    if (!br) return;
    if (br !== txt(r[campo])) upd[campo] = txt(iso);
  };

  const status = txt(r.STATUS_INTEGRACAO).toUpperCase();
  const chave = so(r.CHAVE_NFE);
  let d = null;
  let busca = '';

  if (chave.length === 44) {
    busca = chave;
    d = porChave.get(chave) || null;
  } else if (so(r.NOTA_FISCAL) && so(r.SERIE_NF)) {
    busca = identificacao(r.NOTA_FISCAL, r.SERIE_NF);
    const lista = porNf.get(busca) || [];
    if (lista.length > 1) {
      setTexto('MENSAGEM', 'NF encontrada em mais de uma filial. Informe a CHAVE_NFE na linha.');
    } else {
      d = lista[0] || null;
    }
  }

  if (d) {
    // Faturamento: somente preenche o que estiver vazio
    setTexto('CHAVE_NFE', d.CHAVE_NFE, true, true);
    setTexto('NOTA_FISCAL', so(d.NF_SAIDA).padStart(9, '0'), true, true);
    setTexto('SERIE_NF', normSerie(d.SERIE_NF), true, true);
    setTexto('MARCA', d.MARCA, false, true);
    setTexto('REFERENCIA', d.REFERENCIA, true, true);
    setTexto('DESCRICAO_MATERIAL', d.DESCRICAO_MATERIAL, true, true);
    setTexto('CANAL', d.CANAL, false, true);
    setNumero('QUANTIDADE', d.QUANTIDADE);
    setNumero('VALOR', d.VALOR);
    if (status !== 'INTEGRADO') upd.STATUS_INTEGRACAO = 'INTEGRADO';
    if (txt(r.MENSAGEM)) upd.MENSAGEM = '';

    // Operacional SUL e fiscal: atualiza quando muda
    for (const c of DATAS) setData(c, d[c]);
    setTexto('ROMANEIO', d.ROMANEIO, true);
    setTexto('PLACA', d.PLACA, true);
    setTexto('MOTORISTA', d.MOTORISTA, true);
    setTexto('TRANSPORTADORA', d.TRANSPORTADORA, true);
  } else if (busca && consultadas.has(busca) && status !== 'INTEGRADO' && !upd.MENSAGEM) {
    if (status !== 'NÃO LOCALIZADO') upd.STATUS_INTEGRACAO = 'NÃO LOCALIZADO';
    setTexto('MENSAGEM', 'NF não localizada no faturamento. Verifique número e série.');
  }

  // Recebimento marcado direto na planilha
  if (/^SIM$/i.test(txt(r.RECEBIMENTO_RIO)) && !txt(r.DATA_RECEBIMENTO_RIO)) {
    upd.DATA_RECEBIMENTO_RIO = agora;
  }

  if (Object.keys(upd).length) {
    upd.ULTIMA_ATUALIZACAO = agora;
    out.push({ json: { IDENTIFICACAO: id, ...upd } });
  }
}

return out;
